# New hypothesis: Output is 4 if the input cell (r, c) sits in a 3x3 block that has a 4,
# BUT the 3x3 blocks might have a different structure (not aligned to origin)

# Or maybe it's 3x3 block EXPLICATION - where each output 4 corresponds to a triggered 3x3 region

# Let me check: Find all 3x3 patterns in the input that contain a 4
# Then see where those patterns appear

H, W = 25, 21

# Find all distinct 3x3 patterns containing 4
input_patterns = set()
for r in range(H - 2):
    for c in range(W - 2):
        pattern = tuple(tuple(input1[r+dr][c+dc] for dc in range(3)) for dr in range(3))
        if 4 in val for val in pattern:
            input_patterns.add(pattern)

print(f"Distinct 3x3 patterns in input (in row-major): {len(input_patterns)}")

# Count occurrences of each pattern
from collections import Counter
pattern_counts = Counter()
for r in range(H - 2):
    for c in range(W - 2):
        pattern = tuple(tuple(input1[r+dr][c+dc] for dc in range(3)) for dr in range(3))
        pattern_counts[pattern] += 1

# Most common patterns
print("\nMost common 3x3 patterns:")
for pattern, count in pattern_counts.most_common(10):
    print(f"Pattern (appears {count} times):")
    for row in pattern:
        print("  " + " ".join(map(str, row)))

# Now check if output 4s relate to these patterns
print("\n=== Checking if output 4s match these input patterns ===")
for r in range(H):
    for c in range(W):
        if output1[r][c] == 4:
            # Find which 3x3 patterns in input match a 3x3 around output (r,c)
            found_pattern = None
            pattern_counts_at_position = 0

            for pattern, count in pattern_counts.most_common(10):
                match = True
                for dr in range(3):
                    for dc in range(3):
                        if output1[r+dr][c+dc] != sum(1 for r2 in range(r, min(r+3,H)) 
                                                       for c2 in range(c, min(c+3,W))
                                                       if r2==r+dr and c2==c+dc):
                            pass

            # This is getting complex - let me try simpler approach
            pass

# Let me try: output is 4 if there's a 3x3 input pattern matching exactly at some position
# such that output[r][c] is part of that 3x3 region

print("\n=== Testing: output[r][c]=4 iff input at (r,c) has 3x3 pattern with 4 ===")
for r in [0, 1, 2]:
    for c in [0, 1, 2]:
        if output1[r][c] == 4:
            # Check 3x3 input at same position
            pattern = tuple(tuple(input1[r+dr][c+dc] for dc in range(3)) for dr in range(3))
            print(f"Output({r},{c})=4, Input 3x3 at ({r},{c}):", pattern)
            print(f"  Pattern has 4? {4 in val for val in pattern}")

# Let me try a completely different approach
# What if the transformation is based on counting values in nearby regions?

# Check: For each output cell, count how many of each input value appear in a window
# around that cell

H, W = 25, 21

# Test: output is 4 if count of 0s in some window = some threshold

def count_in_window(r, c, H, W, window=3):
    """Count values in a window around (r, c)"""
    count = Counter()
    for dr in range(-window, window+1):
        for dc in range(-window, window+1):
            rr, cc = r + dr, c + dc
            if 0 <= rr < H and 0 <= cc < W:
                count[input1[rr][cc]] += 1
    return count

# Check for output 4 cells
print("=== For cells where output=4, what do we see in input? ===")
for r in [0, 5, 10, 15, 20]:
    for c in [0, 5, 10]:
        if output1[r][c] == 4:
            cnt = count_in_window(r, c, H, W, 2)  # 5x5 window
            print(f"Output({r},{c})=4: 0s={cnt[0]}, 5s={cnt[5]}, 4s={cnt[4]}")

# Check for output 0 cells
print("\n=== For cells where output=0, what do we see in input? ===")
for r in [0, 5, 10, 15, 20]:
    for c in [0, 5, 10]:
        if output1[r][c] == 0 and input1[r][c] != 5:  # Ignore cells where input already has 5s
            cnt = count_in_window(r, c, H, W, 2)
            print(f"Output({r},{c})=0: 0s={cnt[0]}, 5s={cnt[5]}, 4s={cnt[4]}")
            break
    else:
        continue
    break

# Hmm, the counts seem inconsistent. Let me try 3x3 instead
print("\n=== Same test with 3x3 window ===")
for r in [0, 5, 10]:
    for c in [0, 5, 10]:
        if output1[r][c] == 4:
            cnt = count_in_window(r, c, H, W, 1)
            print(f"Output({r},{c})=4: 0s={cnt[0]}, 5s={cnt[5]}, 4s={cnt[4]}")

# For each input 0, count how many input 4s are nearby
# Test different window sizes and thresholds

H, W = 25, 21

input_4s = [(13, 9), (14, 9), (14, 10), (15, 9), (15, 10)]

# Find all input 0s
input_zeros = [(r, c) for r in range(H) for c in range(W) if input1[r][c] == 0]

print(f"Input zeros: {len(input_zeros)}, Input 4s: {len(input_4s)}")

# For each window size, check if output 4s match input 0s with high count of nearby 4s
for half in range(1, 10):
    correct = 0
    for (r, c) in input_zeros:
        # Count 4s in half-neighborhood
        count = 0
        for dr in range(-half, half+1):
            for dc in range(-half, half+1):
                rr, cc = r + dr, c + dc
                if (rr, cc) in input_4s:
                    count += 1

        # Output is prediction (True if we think output should be 4)
        pred = (count > 0)
        actual = (output1[r][c] == 4)
        if pred == actual:
            correct += 1

    rate = correct / len(input_zeros)
    print(f"Window size {2*half+1}, threshold > 0: {rate*100:.1f}% correct ({correct}/{len(input_zeros)})")

# Try different thresholds
print("\n=== With window size 3, different thresholds ===")
half = 1
correct_by_thresh = {}
for (r, c) in input_zeros:
    count = 0
    for dr in range(-half, half+1):
        for dc in range(-half, half+1):
            rr, cc = r + dr, c + dc
            if (rr, cc) in input_4s:
                count += 1

    if count == 1:
        pred = True
    elif count == 0:
        pred = False
    else:
        pred = count > half  # Try thresholds: >=2, >=3, etc.

    actual = (output1[r][c] == 4)
    if pred == actual:
        correct_by_thresh[pred] = correct_by_thresh.get(pred, 0) + 1

for thresh, correct in sorted(correct_by_thresh.items()):
    print(f"Threshold {thresh}: {correct*100/len(input_zeros):.1f}% correct")

# Let me try a completely different hypothesis
# What if output[r][c] = 4 if the input has a certain property at (r,c)?

# Check: what's the pattern of 5s and 0s at positions that become 4?

H, W = 25, 21

input_5s = {(r, c) for r in range(H) for c in range(W) if input1[r][c] == 5}
input_4s = {(r, c) for r in range(H) for c in range(W) if input1[r][c] == 4}

# Count 5s neighboring each output 4
def count_5_neighbors(r, c):
    """Count how many of the 8 neighbors are 5s"""
    count = 0
    for dr in range(-1, 2):
        for dc in range(-1, 2):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                if input1[nr][nc] == 5:
                    count += 1
    return count

def count_4_neighbors(r, c):
    """Count how many of the 8 neighbors are 4s"""
    count = 0
    for dr in range(-1, 2):
        for dc in range(-1, 2):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dc
            if 0 <= nr < H and 0 <= nc < W:
                if input1[nr][nc] == 4:
                    count += 1
    return count

# Check threshold: is there a number of 5- or 4-neighbors that predicts output=4?
print("=== Threshold analysis ===")

zeros_to_4 = []
zeros_stay_0 = []

for r in range(H):
    for c in range(W):
        if input1[r][c] == 0:
            neighbors_5 = count_5_neighbors(r, c)
            neighbors_4 = count_4_neighbors(r, c)

            if output1[r][c] == 4:
                zeros_to_4.append((r, c, neighbors_5, neighbors_4))
            else:
                zeros_stay_0.append((r, c, neighbors_5, neighbors_4))

# Distribution of 5-neighbors
def dist_to_4d(names):
    for name in names:
        vals = [t for t in zip(*[t.get(n, 0) for n in name])][5]
        print(f"{name}: min={min(vals)}, max={max(vals)}, avg={sum(vals)/len(vals):.1f}")

print("Zeros->4:")
dist_to_4d(['[r,c,5,4][5][5][5][:5]'])  # Actually this is wrong

# Let me recalculate more carefully
print("\n=== Stats for zeros that become 4 ===")
max_5 = max(t[2] for t in zeros_to_4)
min_5 = min(t[2] for t in zeros_to_4)
avg_5 = sum(t[2] for t in zeros_to_4) / len(zeros_to_4)
print(f"5-neighbors: min={min_5}, max={max_5}, avg={avg_5:.1f}")

print("\n=== Stats for zeros that stay 0 ===")
max_5 = max(t[2] for t in zeros_stay_0)
min_5 = min(t[2] for t in zeros_stay_0)
avg_5 = sum(t[2] for t in zeros_stay_0) / len(zeros_stay_0)
print(f"5-neighbors: min={min_5}, max={max_5}, avg={avg_5:.1f}")

# So there IS a difference! Let me see if that's the deciding factor
# Maybe threshold is: 5-neighbors >= some_value OR 4-neighbors >= some_value?

# Check min number of 5-neighbors for zeros that become 4
print("\n=== Min 5-neighbors for zeros->4 ===")
for (r, c, n5, n4) in sorted(zeros_to_4, key=lambda x: x[2])[:5]:
    print(f"  ({r},{c}): {n5} 5-neighbors, {n4} 4-neighbors")

# Check max number of 5-neighbors for zeros that stay 0
print("\n=== Max 5-neighbors for zeros->0 ===")
for (r, c, n5, n4) in sorted(zeros_stay_0, key=lambda x: -x[2])[:5]:
    print(f"  ({r},{c}): {n5} 5-neighbors, {n4} 4-neighbors")

