# Verify the Chebyshev <= 13 hypothesis directly
output_4s = {(r, c) for r in range(25) for c in range(21) if output1[r][c] == 4}
input_4s = {(r, c) for r in range(25) for c in range(21) if input1[r][c] == 4}

def chebyshev_dist_to_4s(r, c):
    """Chebyshev distance to nearest input 4"""
    min_dist = 999
    for (ir, ic) in input_4s:
        d = max(abs(r - ir), abs(c - ic))
        if d < min_dist:
            min_dist = d
    return min_dist

# Build output based on Chebyshev threshold
output_cheb = [[input1[r][c] for c in range(21)] for r in range(25)]
for r in range(25):
    for c in range(21):
        if chebyshev_dist_to_4s(r, c) <= 13:
            output_cheb[r][c] = 4

# Compare
correct = 0
wrong = 0
for r in range(25):
    for c in range(21):
        pred = output_cheb[r][c] == 4
        actual = output1[r][c] == 4
        if pred == actual:
            correct += 1
        else:
            wrong += 1

print(f"Chebyshev <= 13: {correct} correct, {wrong} wrong out of {25*21}")
print(f"Predicted 4s: {sum(cell == 4 for row in output_cheb for cell in row)}")
print(f"Actual 4s: {len(output_4s)}")

# Find mismatches
print("\n=== Mismatches ===")
for r in range(25):
    for c in range(21):
        pred = output_cheb[r][c] == 4
        actual = output1[r][c] == 4
        if pred != actual:
            d = chebyshev_dist_to_4s(r, c)
            print(f"({r},{c}): pred={pred}, actual={actual}, cheb_dist={d}")

# OK so there are mismatches with Chebyshev <= 13.
# Let me try Chebyshev <= 12
print("\n=== Chebyshev <= 12 ===")
output_cheb12 = [[input1[r][c] for c in range(21)] for r in range(25)]
for r in range(25):
    for c in range(21):
        if chebyshev_dist_to_4s(r, c) <= 12:
            output_cheb12[r][c] = 4

correct12 = sum(1 for r in range(25) for c in range(21) 
                if (output_cheb12[r][c] == 4) == (output1[r][c] == 4))
print(f"Chebyshev <= 12: {correct12} correct, {25*21 - correct12} wrong")
print(f"Predicted 4s: {sum(cell == 4 for row in output_cheb12 for cell in row)}")

# It's very close to 180. Let me see what the 180th cell is
# Chebyshev <= 11 gives 175 cells
# Chebyshev <= 12 gives 179 cells
# Chebyshev <= 13 gives 180 cells

# Let me list the cells at each Chebyshev distance
from collections import defaultdict
dist_cells = defaultdict(list)
for r in range(25):
    for c in range(21):
        d = chebyshev_dist_to_4s(r, c)
        dist_cells[d].append((r, c))

print("\n=== Cells at each Chebyshev distance ===")
cumulative = 0
for d in sorted(dist_cells.keys()):
    count_at_d = len(dist_cells[d])
    cumulative += count_at_d
    print(f"Chebyshev = {d}: {count_at_d} cells, cumulative: {cumulative}")
    if count_at_d > 0:
        print(f"  Cells: {dist_cells[d]}")

# Key insight: Chebyshev <= 13 gives 180 cells, but SOME of those don't match.
# Some cells that SHOULD be 4 (in the expansion region) are NOT 4.
# So it's NOT all Chebyshev <= 13. Let me debug further.

output_4s = {(r, c) for r in range(25) for c in range(21) if output1[r][c] == 4}
input_4s = {(r, c) for r in range(25) for c in range(21) if input1[r][c] == 4}

def chebyshev_dist_to_4s(r, c):
    min_dist = 999
    for (ir, ic) in input_4s:
        d = max(abs(r - ir), abs(c - ic))
        if d < min_dist:
            min_dist = d
    return min_dist

# Build Chebyshev <= 13 and compare
cheb_13_4s = set()
for r in range(25):
    for c in range(21):
        if chebyshev_dist_to_4s(r, c) <= 13:
            cheb_13_4s.add((r, c))

# Find mismatches
mismatch_out = cheb_13_4s - output_4s  # Should be 4 but isn't
mismatch_in = output_4s - cheb_13_4s  # Is 4 but shouldn't be

print(f"Should be 4 but isn't ({len(mismatch_out)}):")
for r in sorted(mismatch_out):
    print(f"  ({r[0]}, {r[1]}) - dist={chebyshev_dist_to_4s(r[0], r[1])}")

print(f"\nIs 4 but shouldn't be ({len(mismatch_in)}): NONE (all are dist <= 13)")

# So the issue is: cells at Chebyshev distance 13 are NOT 4, but ones at dist < 13 mostly ARE.
# Let me look more carefully at distance 13

dist_13 = set()
for r, c in mismatch_out:
    dist_13.add((r, c))

print(f"\nDist 13 cells that should be 4: {len(dist_13)}")
for r, c in sorted(dist_13):
    print(f"  ({r},{c})")

# The problem might be that ALL 4s come from the INPUT SEEDS at distance 13
# The input seeds form a block themselves, so the expansion might NOT be radial from each seed
# but from the SEED CLUSTER

# Let me try something different: what if I filter by what's IN input 1?
# Maybe only cells must be 0 (background) in input to become 4?

no_input = set()
for r in range(25):
    for c in range(21):
        if output1[r][c] == 4 and input1[r][c] == 0:
            no_input.add((r, c))

print(f"\nOutput 4s where input was 0: {len(no_input)}")
print(f"Complete subset: {no_input == output_4s}")

# Check if the source of "missing" cells is input being non-0
missing = cheb_13_4s - output_4s
missing_input_nonzero = 0
for r, c in missing:
    if input1[r][c] != 0:
        missing_input_nonzero += 1

print(f"Missing cells with non-zero input: {missing_input_nonzero}")

# So the rule appears to be: cell becomes 4 if (Chebyshev dist <= 13) AND (input is 0)
# But that gives: 5 + 14 + 22 + 30 + 38 + 46 + 54 + 62 + 70 + 78 + 42 + 22 + 21 - 5 = ?
# Wait, need to subtract the input 4s themselves (they're dist 0 and input is already 4)

actual_4s = 0
for r in range(25):
    for c in range(21):
        d = chebyshev_dist_to_4s(r, c)
        in_zero = input1[r][c] == 0
        if d <= 13 and in_zero:
            actual_4s += 1

print(f"\nCount with (Chebyshev<=13 AND input==0): {actual_4s}")

# But wait, let me verify MORE carefully
print(f"\nActual output 4s total: {len(output_4s)}")

# Let me check - is it possible THAT all the output_4s satisfy (Chebyshev<=13 AND input==0)?
all_satisfy = True
for r, c in output_4s:
    d = chebyshev_dist_to_4s(r, c)
    if d > 13 or input1[r][c] != 0:
        all_satisfy = False
        print(f"Fail: ({r},{c}) d={d} input={input1[r][c]}")

print(f"\nAll output 4s satisfy rule: {all_satisfy}")

# Now check if any cell with (Chebyshev<=13 AND input==0) is NOT an output 4
extra = 0
for r in range(25):
    for c in range(21):
        d = chebyshev_dist_to_4s(r, c)
        if d <= 13 and input1[r][c] == 0 and output1[r][c] != 4:
            extra += 1
            if extra <= 5:
                print(f"Extra: ({r},{c}) d={d}")

print(f"\nExtra cells (should be 4 but aren't): {extra}")

# Let me fix the visualization and do more analysis

output_4s = {(r, c) for r in range(25) for c in range(21) if output1[r][c] == 4}
input_4s = {(r, c) for r in range(25) for c in range(21) if input1[r][c] == 4}
input_4_set = set(input_4s)

print("=== Visual pattern ===")
for row in range(25):
    s = ''
    for c in range(21):
        if output1[row][c] == 4:
            s += 'X'
        elif input1[row][c] == 4:
            s += 'S'  # seed that stays 4
        else:
            s += '.'
    print(s)

# Let me check column 20 (the last column) for extent
col20_4s = [(r, c) for r in range(25) for c in [20] if output1[r][c] == 4]
col20_non_4s = [(r, c) for r in range(25) for c in [20] if output1[r][c] != 4]
print(f"\nCol 20 (last): {len(col20_4s)} 4s at rows {sorted([r for r, c in col20_4s])}")

col21_4s = [(r, c) for r in range(25) for c in [21] if output1[r][c] == 4]
print(f"Col 21 (out of bounds - checking 21s): {len(col21_4s)} cells")

# Hmm, let me check all columns for boundary behavior
col_stats = []
for col in range(21):
    rows_with_4 = sorted([r for r in range(25) if output1[r][col] == 4])
    if rows_with_4:
        col_stats.append((col, len(rows_with_4), rows_with_4[0], rows_with_4[-1]))

print(f"\n=== Per-column statistics ===")
for col, cnt, first, last in sorted(col_stats, key=lambda x: x[0]):
    print(f"Col {col:2d}: {cnt:2d} cells at row {first}-{last}")

# Now I have a visual of the pattern. Let me analyze it systematically
# The pattern shown above is the actual output. 'X' = output 4, 'S' = input seed 4

# Looking at the pattern:
# - Rows near the input seed cluster (rows 9-16) look different
# - Top rows have sparse 4s
# - Bottom rows have sparse 4s
# - Some columns are completely empty (e.g., cols 2-6 have few cells)

# Let me try a very different hypothesis:
# What if the pattern is based on L1 (Manhattan) distance instead of L∞ (Chebyshev)?

output_4s = {(r, c) for r in range(25) for c in range(21) if output1[r][c] == 4}
input_4s = {(r, c) for r in range(25) for c in range(21) if input1[r][c] == 4}

def manhattan_dist_to_4s(r, c):
    min_dist = 999
    for (ir, ic) in input_4s:
        d = abs(r - ir) + abs(c - ic)
        if d < min_dist:
            min_dist = d
    return min_dist

# What's the max Manhattan distance?
max_manhattan = 0
for r, c in output_4s:
    d = manhattan_dist_to_4s(r, c)
    if d > max_manhattan:
        max_manhattan = d
print(f"Max Manhattan distance of output 4s: {max_manhattan}")

# Can we find a threshold T such that output == {cells with Man(Therman) <= T AND input == 0}?
# Let me iterate

for thresh in range(20, max_manhattan + 5):
    pred_4s = set()
    for r in range(25):
        for c in range(21):
            if manhattan_dist_to_4s(r, c) <= thresh:
                pred_4s.add((r, c))

    correct = sum(1 for r in range(25) for c in range(21) 
                  if ((r, c) in pred_4s) == (output1[r][c] == 4))
    wrong = 25 * 21 - correct
    print(f"Manhattan <= {thresh}: {correct} correct, {wrong} wrong")

# Also try Chebyshev again more carefully
def chebyshev_dist_to_4s(r, c):
    min_dist = 999
    for (ir, ic) in input_4s:
        d = max(abs(r - ir), abs(c - ic))
        if d < min_dist:
            min_dist = d
    return min_dist

print("\n=== Chebyshev thresholds ===")
for thresh in range(10, max_manhattan + 5):
    pred_4s = set()
    for r in range(25):
        for c in range(21):
            if chebyshev_dist_to_4s(r, c) <= thresh:
                pred_4s.add((r, c))

    correct = sum(1 for r in range(25) for c in range(21) 
                  if ((r, c) in pred_4s) == (output1[r][c] == 4))
    wrong = 25 * 21 - correct
    print(f"Chebyshev <= {thresh}: {correct} correct, {wrong} wrong")

# Let me debug this more carefully

output_4s = set()
for r in range(25):
    for c in range(21):
        if output1[r][c] == 4:
            output_4s.add((r, c))

input_4s = set()
for r in range(25):
    for c in range(21):
        if input1[r][c] == 4:
            input_4s.add((r, c))

print(f"Output 4s count: {len(output_4s)}")
print(f"Input 4s count: {len(input_4s)}")
print(f"Input 4s: {sorted(input_4s)}")

def chebyshev_dist_to_4s(r, c):
    min_dist = 999
    for (ir, ic) in input_4s:
        d = max(abs(r - ir), abs(c - ic))
        if d < min_dist:
            min_dist = d
    return min_dist

# Test on a specific cell that I know should be 4
r, c = 13, 9  # This is an input seed
d = chebyshev_dist_to_4s(r, c)
print(f"\nCell ({r},{c}): input 4, dist to nearest input 4 = {d}")

# Check what cells at Chebyshev <= 13 look like
print("\n=== Sample Chebyshev <= 13 cells ===")
for offset_r in [-10, -5, 0, 5, 10]:
    for offset_c in [-10, -5, 0, 5, 10]:
        if offset_r == 0 and offset_c == 0: continue
        r2, c2 = 14 + offset_r, 10 + offset_c  # Near seed
        if 0 <= r2 < 25 and 0 <= c2 < 21:
            d2 = chebyshev_dist_to_4s(r2, c2)
            if d2 <= 13:
                in_output = (r2, c2) in output_4s
                in_input = (r2, c2) in input_4s
                print(f"({r2},{c2}): Chebyshev={d2}, in_output={in_output}, in_input={in_input}")

# Let me re-count with Chebyshev <= 13
pred_4s = set()
for r in range(25):
    for c in range(21):
        if chebyshev_dist_to_4s(r, c) <= 13:
